#!/bin/zsh
# mix.sh <a2 file> <out.wav>
set -e; cd "$(dirname "$0")"
FF=$(/opt/homebrew/opt/python@3.11/bin/python3.11 -c "import imageio_ffmpeg; print(imageio_ffmpeg.get_ffmpeg_exe())")
S="aformat=sample_rates=48000:channel_layouts=stereo"
OFF=${3:-0}
"$FF" -y -loglevel error -i ayla-site/audio/cipher.mp3 -i vo4/n1.wav -i vo4/a1.wav -i "$1" -i vo4/a3.wav -i vo4/p1.wav -i vo4/f1.wav -i vo4/a4.wav -i vo4/f2.wav -i vo4/n2.wav -i vo4/n3.wav -i vo4/n4.wav -i vo4/f3.wav -i vo4/a5.wav -i sys/beep.wav -i sys/s_acces_fx.wav -i sys/s_ident_fx.wav -i sys/s_profil_fx.wav -i sys/s_compte_fx.wav -i sys/s_dossier_fx.wav \
 -filter_complex "[0:a]atrim=0:$(( 92+OFF/1000 )),volume=0.28,afade=t=in:st=0:d=1.5,afade=t=out:st=$(( 87+OFF/1000 )):d=4.5,${S}[m];[1:a]adelay=$(( 700+OFF ))|$(( 700+OFF )),${S}[v1];[2:a]adelay=$(( 14900+OFF ))|$(( 14900+OFF )),${S}[v2];[3:a]adelay=$(( 25300+OFF ))|$(( 25300+OFF )),${S}[v3];[4:a]adelay=$(( 33900+OFF ))|$(( 33900+OFF )),${S}[v4];[5:a]adelay=$(( 36500+OFF ))|$(( 36500+OFF )),${S}[v5];[6:a]adelay=$(( 38200+OFF ))|$(( 38200+OFF )),${S}[v6];[7:a]adelay=$(( 44100+OFF ))|$(( 44100+OFF )),${S}[v7];[8:a]adelay=$(( 47700+OFF ))|$(( 47700+OFF )),${S}[v8];[9:a]adelay=$(( 55000+OFF ))|$(( 55000+OFF )),${S}[v9];[10:a]adelay=$(( 61300+OFF ))|$(( 61300+OFF )),${S}[v10];[11:a]adelay=$(( 67800+OFF ))|$(( 67800+OFF )),${S}[v11];[12:a]adelay=$(( 75200+OFF ))|$(( 75200+OFF )),${S}[v12];[13:a]adelay=$(( 79200+OFF ))|$(( 79200+OFF )),${S}[v13];[14:a]asplit=7[b1][b2][b3][b4][b5][b6][b7];[b1]adelay=$(( 11000+OFF ))|$(( 11000+OFF )),${S}[k1];[b2]adelay=$(( 13000+OFF ))|$(( 13000+OFF )),${S}[k2];[b3]adelay=$(( 18100+OFF ))|$(( 18100+OFF )),${S}[k3];[b4]adelay=$(( 19800+OFF ))|$(( 19800+OFF )),${S}[k4];[b5]adelay=$(( 20900+OFF ))|$(( 20900+OFF )),${S}[k5];[b6]adelay=$(( 22000+OFF ))|$(( 22000+OFF )),${S}[k6];[b7]adelay=$(( 23100+OFF ))|$(( 23100+OFF )),${S}[k7];[15:a]adelay=$(( 11350+OFF ))|$(( 11350+OFF )),${S}[r1];[16:a]adelay=$(( 13350+OFF ))|$(( 13350+OFF )),${S}[r2];[17:a]adelay=$(( 18450+OFF ))|$(( 18450+OFF )),${S}[r3];[18:a]adelay=$(( 21050+OFF ))|$(( 21050+OFF )),${S}[r5];[19:a]adelay=$(( 23350+OFF ))|$(( 23350+OFF )),${S}[r7];[m][v1][v2][v3][v4][v5][v6][v7][v8][v9][v10][v11][v12][v13][k1][k2][k3][k4][k5][k6][k7][r1][r2][r3][r5][r7]amix=inputs=26:normalize=0:duration=first[a]" -map "[a]" -t $(( 92+OFF/1000 )) -c:a pcm_s16le "$2"
"$FF" -i "$2" 2>&1 | grep -o "Duration: [0-9:.]*"
